class Solution {
    public int numberOfUniqueGoodSubsequences(String binary){
        long zero=0,one=0,mod=1_000_000_007;
        boolean hasZero=false;
        for(char value:binary.toCharArray())if(value=='0'){
            zero=(zero+one)%mod;
            hasZero=true;
        }else one=(zero+one+1)%mod;
        return (int)((zero+one+(hasZero?1:0))%mod);
    }
}

code.kotlin:
class Solution {
    fun numberOfUniqueGoodSubsequences(binary:String):Int{
        val mod=1_000_000_007L;
        var zero=0L;
        var one=0L;
        var hasZero=false;
        for(value in binary)if(value=='0'){
            zero=(zero+one)%mod;
            hasZero=true
        }else one=(zero+one+1)%mod;
        return ((zero+one+if(hasZero)1 else 0)%mod).toInt()
    }
}

